function login(){}
function login_(openBrowser, checkMode) {
    // java.removeCookie("snssdk.com")
    var cookie_ = String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() ? source.getLoginInfoMap() : {})['手动登录Token']
    // java.toast(cookie_)
    if (cookie_ && cookie_ != "" && !checkMode) {
        if (!source.variableComment) {
            java.toast("请不要重复登录，请先退出登录！")
        } else {
            java.toast("您为填写token登录，请手动移除token后再次登录")
        }
        return false
    }
    if (openBrowser) {
        try {
            java.startBrowserAwait("https://fanqienovel.com/", "登录")
        } catch (e) {
            java.toast(e)
        }
    }
    // java.log("snssdk cookie: " + java.getCookie("snssdk.com") + "will be reomved")
    try {
        cookie.removeCookie("snssdk.com")
    } catch (e) {}
    // java.log(cookie)
    var cookie_ = "sessionid=" + String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap())['手动登录Token']
    let user
    try {
      user = JSON.parse(java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({
        method: "GET",
        headers: {
          "Cookie": cookie_
        }
      }))).data.name
     } catch (e) {java.log(e)}
    if (!cookie_ || cookie_ == "sessionid=" || !user) {
        java.toast("未获取到登录凭据，登录失败")
        return false
    }
    java.toast("欢迎 " + user + "\n登录成功！")
    return true
}
function Y(a, b) {
  try {
    login_(a, b)
  } catch (e) {
    java.log(e+"\n"+e.stack)
  }
}
function X() {
    cookie.removeCookie("fanqienovel.com");
    cookie.removeCookie("snssdk.com");
    if (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() ? source.getLoginInfoMap() : {})['手动登录Token']) java.toast("请手动移除填写的Token")
    else java.toast("退出登录成功");
}

n.jsLib:
function splitArray(input, size) {
  const output = []
  for (let i = 0; i < input.length; i += size) {
    output.push(input.slice(i, i + size))
  }
  return output
}
function write_config(key, value) {
  if (Packages.android.text.TextUtils.isEmpty(this.source.getVariable())) {
    this.source.setVariable('{}')
  }
  // this.java.log('var:' + this.source.getVariable())
  let obj = JSON.parse(this.source.getVariable())
  let arr = key.split('.')
  let temp = obj

  for (let i = 0; i < arr.length - 1; i++) {
    let currentKey = arr[i]
    if (!temp[currentKey]) {
      temp[currentKey] = {}
    }
    temp = temp[currentKey]
  }
  temp[arr[arr.length - 1]] = value
  this.source.setVariable(JSON.stringify(obj))
}
function read_config(key) {
  if (Packages.android.text.TextUtils.isEmpty(this.source.getVariable())) {
    this.source.setVariable('{}')
  }
  // this.java.log('var:' + this.source.getVariable())
  let obj = JSON.parse(this.source.getVariable())
  let arr = key.split('.')
  let res = JSON.parse(JSON.stringify(obj))
  for (let i = 0; i < arr.length; i++) {
    res = res[arr[i]] || (i < (arr.length - 1) ? {} : undefined)
    // this.java.log(JSON.stringify(res))
  }
  return res
}
function getBookId(url, page) {
  const {java} = this
  let $ = JSON.parse(url).data
  let list
  let arr
  if ($.book_shelf_info != 0 && $.book_shelf_info != undefined) {
   arr = $.book_shelf_info.map($ => $.book_id)
  } else if (let (list = $.data_list) list != 0 && $.data_list != undefined)  {
    arr = $.data_list.map($ => $.book_id_str)
  } else {
    java.toast("获取 book_id 失败，你可能需要登录！")
  }
  return arr.slice(page*100, (page+1)*100)
}

